// Des: Entry point: port arg, scheduler, HTTP server
// Flo: main > port from argv (default 4000, clear of cli-run 3010 and old hub 3000) > ui root and project root next to exe > POSIX orphan sweep after kill -9 (Windows: KILL_ON_JOB_CLOSE) > scheduler star BEFORE servStar (accept loop never returns) > POSIX signal stop (handler may not alloc, lock or do io: kills loop children via file-scope pointer) > servStar
// I/O: argv[1] optional port (u16) > listening HTTP server, never returns until killed; usage auto-task.exe [port] [jobs-file.json]
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const serv = @import("server"); const tick = @import("ticker"); const spaw = @import("spawn"); const stor = @import("store"); const tkst = @import("taskstore");
const CF = .{ .sepa = std.fs.path.sep_str };
pub fn main(init: std.process.Init) !void { const iozz = init.io; const gpaz = init.gpa; const allo = init.arena.allocator(); const exez_dirz = std.process.executableDirPathAlloc(iozz, allo) catch "."; const proj_root = projRootFind(allo, iozz, exez_dirz); if (stor.confLoad(allo, iozz, proj_root)) |warn| std.debug.print("  warn: {s}\n", .{warn}); var port: u16 = stor.tune.port; var args = init.minimal.args; var iter = args.iterateAllocator(allo) catch { return servLaun(gpaz, iozz, allo, port, exez_dirz, proj_root); }; _ = iter.next(); if (iter.next()) |argz| { port = std.fmt.parseInt(u16, argz, 10) catch stor.tune.port; } if (iter.next()) |jobz| { if (!tkst.jobzFileSet(jobz)) std.debug.print("  warn: bad jobs file name, using the default\n", .{}); } return servLaun(gpaz, iozz, allo, port, exez_dirz, proj_root); }
fn servLaun(gpaz: std.mem.Allocator, iozz: std.Io, allo: std.mem.Allocator, port: u16, exez_dirz: []const u8, proj_root: []const u8) !void { const uizz_root = uizzRootFind(allo, iozz, exez_dirz); const swep = spaw.orphSwee(allo, iozz); if (swep > 0) std.debug.print("  swept {d} orphaned process group(s) from the last run\n", .{swep}); var sche: tick.Sche = .{}; sche.star(gpaz, iozz, proj_root) catch |erro| { std.debug.print("  warn: scheduler did not start ({t}) — commands still work\n", .{erro}); }; defer sche.dein(); sigzStopInst(&sche); serv.servStar(gpaz, iozz, port, uizz_root, &sche) catch |erro| { switch (erro) { error.AddressInUse => { std.debug.print("\n  error: port {d} is already in use.\n  try:   auto-task {d}\n\n", .{ port, port + 1 }); }, else => std.debug.print("\n  server error: {t}\n\n", .{erro}) } std.process.exit(1); }; }
var glob_sche: ?*tick.Sche = null;
fn sigzStopInst(sche: *tick.Sche) void { if (builtin.os.tag == .windows) return; glob_sche = sche; var acti: std.posix.Sigaction = .{ .handler = .{ .handler = sigzStopCall }, .mask = std.posix.sigemptyset(), .flags = 0 }; std.posix.sigaction(std.posix.SIG.INT, &acti, null); std.posix.sigaction(std.posix.SIG.TERM, &acti, null); std.posix.sigaction(std.posix.SIG.HUP, &acti, null); var igno: std.posix.Sigaction = .{ .handler = .{ .handler = std.posix.SIG.IGN }, .mask = std.posix.sigemptyset(), .flags = 0 }; std.posix.sigaction(std.posix.SIG.PIPE, &igno, null); }
fn sigzStopCall(_: std.posix.SIG) callconv(.c) void { if (glob_sche) |sche| sche.loopEmerStop(); std.process.exit(0); }
fn uizzRootFind(allo: std.mem.Allocator, iozz: std.Io, exez_dirz: []const u8) []const u8 { return projRootFind(allo, iozz, exez_dirz); }
fn projRootFind(allo: std.mem.Allocator, iozz: std.Io, exez_dirz: []const u8) []const u8 { const cand = [_][]const u8{ ".." ++ CF.sepa ++ "..", "..", "." }; for (cand) |rela| { const path = std.fs.path.resolve(allo, &.{ exez_dirz, rela }) catch continue; const prob = std.fs.path.join(allo, &.{ path, "build.zig" }) catch continue; _ = std.Io.Dir.cwd().statFile(iozz, prob, .{}) catch continue; return path; } return exez_dirz; }
